
const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Cerrar':'Menú';nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menú'}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menú';menu.focus()}});document.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('details').forEach(other=>{if(other!==d)other.open=false})}));

const intelligenceStages=[{"name": "Brief y contexto", "input": "El brief, las restricciones y las fuentes disponibles.", "work": "Investigamos mercado, competencia, consumidor y entorno con apoyo de IA y revisión experta.", "output": "Un contexto estratégico que orienta las preguntas del proyecto.", "review": "Si cambia una premisa del negocio, revisamos los objetivos y el alcance."}, {"name": "Objetivos de investigación", "input": "El contexto comprendido y la decisión que necesita apoyar el cliente.", "work": "Traducimos el reto en objetivos, preguntas clave y un plan de investigación.", "output": "Objetivos acordados que dan propósito a cada análisis.", "review": "Contrastamos nuevas preguntas con la necesidad original para mantener el enfoque."}, {"name": "Arquitectura analítica", "input": "Los objetivos y las respuestas que necesitamos obtener.", "work": "Diseñamos módulos, modelos y variables antes de construir el instrumento.", "output": "Una ruta: pregunta de negocio → respuesta esperada → análisis → información necesaria.", "review": "Si falta una variable o un análisis no responde al objetivo, ajustamos el diseño."}, {"name": "Muestra y cuestionario", "input": "La arquitectura analítica y la población que queremos comprender.", "work": "Diseñamos o apoyamos muestra, cuestionario y validación del instrumento. Acordamos quién realiza el levantamiento.", "output": "Un instrumento alineado con los análisis y un plan de obtención de información.", "review": "El pretest y la viabilidad del campo pueden requerir revisar preguntas y cobertura."}, {"name": "Validación y calidad de datos", "input": "La base obtenida y el cuestionario, o las fuentes acordadas para el proyecto.", "work": "Relacionamos variables y estructura; aplicamos controles y revisamos anomalías y faltantes.", "output": "Una base revisada y límites documentados para la ejecución.", "review": "Una inconsistencia puede exigir corregir datos o acotar un análisis, no ocultar el problema."}, {"name": "Ejecución analítica", "input": "La base revisada, la arquitectura y los criterios del proyecto.", "work": "Desarrollamos scripts y ejecutamos modelos y análisis; contrastamos consistencia y resultados.", "output": "Resultados reproducibles vinculados con las preguntas de negocio.", "review": "Los diagnósticos pueden requerir ajustar el modelo y revisar los supuestos."}, {"name": "Descubrimiento de insights", "input": "Los resultados del plan, el contexto y los hallazgos adicionales.", "work": "Integramos y contrastamos evidencia, exploramos patrones y priorizamos implicaciones.", "output": "Insights que explican qué significa el resultado y por qué importa.", "review": "Un hallazgo adicional se valida antes de incorporarlo a la historia o abrir otra pregunta."}, {"name": "Entrega ejecutiva", "input": "Los insights priorizados y la decisión original.", "work": "Construimos la narrativa, los soportes y las recomendaciones; desarrollamos herramientas según el alcance.", "output": "Una presentación, reporte o herramienta con contexto, evidencia y límites.", "review": "Las preguntas del equipo retroalimentan la interpretación; el seguimiento se acuerda con el cliente."}];
const applications=[{"title": "Elección, precios y simulación", "question": "Investigación y software para evaluar ofertas y precios.", "status": "INVESTIGACIÓN APLICADA + DESARROLLO INTERACTIVO", "intro": "Diseñamos y analizamos ejercicios de elección para entender cómo se relacionan atributos, precio y promociones con la preferencia. Desarrollamos un simulador para consultar resultados y comparar alternativas.", "anchor": "¿Qué atributos y precios conviene evaluar para construir una oferta relevante?", "limit": "Alcance: estimación de preferencias bajo el diseño del estudio. Las simulaciones no equivalen a pronósticos de ventas y deben leerse con sus supuestos.", "steps": ["El brief se enriquece con información pública de la categoría y sus alternativas. Ese contexto acompaña las decisiones posteriores.", "Se concreta qué necesitamos conocer sobre elección, atributos y precio para evaluar la oferta.", "Traducimos cada pregunta en un módulo: elección entre ofertas, sensibilidad al precio o prioridades. Definimos modelos, variables y estímulos antes del cuestionario.", "El diseño de elección y las preguntas de precio se alinean con los módulos seleccionados. En estos trabajos, el cliente realizó el levantamiento.", "La base se contrasta con el cuestionario y el diseño de los ejercicios antes de estimar resultados.", "Programamos los análisis para estimar utilidades, importancia de atributos y preferencias; integramos los módulos de precio y prioridades previstos en la arquitectura.", "Los resultados de los distintos módulos se contrastan para explicar diferencias y alternativas, más allá de leer gráficos por separado.", "Entregamos una presentación con insights y soportes, junto con un simulador o reporteador que permite consultar perfiles y comparar ofertas según el alcance acordado."], "built": "Diseño experimental, scripts analíticos y un simulador o reporteador que convierte las estimaciones en una herramienta de consulta.", "method": "Conjoint de elección para estimar utilidades e importancias; sensibilidad al precio y MaxDiff según los módulos acordados. Revisamos diseño, bases y consistencia antes de interpretar.", "delivered": "Presentación ejecutiva, resultados de soporte y simulador con filtros y guía de uso para explorar escenarios dentro del modelo."}, {"title": "Text Analytics y desarrollo", "question": "De respuestas abiertas a información que puede analizarse.", "status": "ANÁLISIS DE TEXTO + SOFTWARE PROPIO", "intro": "Estructuramos comentarios y respuestas abiertas para identificar temas, asociaciones y diferencias entre perfiles. También desarrollamos un motor propio de clasificación para apoyar este trabajo con IA y revisión humana.", "anchor": "¿Qué expresan las personas, cómo se relacionan los temas y qué implica para el negocio?", "limit": "Alcance: clasificación y análisis interpretativo con revisión humana. La frecuencia de un tema no demuestra su importancia comercial; el motor no se atribuye a todos los estudios.", "steps": ["El brief y el contexto permiten entender para qué necesitamos escuchar a las personas y qué fuentes son pertinentes.", "Se definen las preguntas que guiarán la lectura de opiniones y su relación con otras medidas del estudio.", "Se acuerda cómo analizar e integrar textos, atributos y resultados cuantitativos, y qué información requiere cada módulo.", "Se apoyan preguntas abiertas e instrumentos que permitan responder a los objetivos, según el diseño y las fuentes del proyecto.", "Se revisan estructura, cobertura y textos disponibles antes de su integración analítica.", "Procesamos los textos, clasificamos respuestas y analizamos patrones y asociaciones. El motor propio puede asistir la clasificación con IA; la revisión humana resuelve ambigüedades y verifica su utilidad.", "Se contrastan temas, diferencias y evidencia cuantitativa para elaborar una interpretación contextualizada.", "Entregamos resultados trazables en bases codificadas, tablas, visualizaciones y presentación. Las herramientas de consulta se incluyen según el alcance."], "built": "Un motor de procesamiento y clasificación de texto, con revisión de casos ambiguos, controles y salidas para análisis. Es una capacidad propia que se incorpora según el proyecto.", "method": "Preparación de textos, definición de categorías, clasificación temática o semántica y revisión experta. En estudios aplicados, integramos evidencia cualitativa y cuantitativa para interpretar las diferencias.", "delivered": "Bases codificadas, tablas y visualizaciones de temas, asociaciones y perfiles; una presentación que conecta esos resultados con la pregunta de negocio."}, {"title": "Auditoría de video con IA", "question": "Software con IA para auditar atención visual en publicidad.", "status": "DESARROLLO PROPIO · PILOTO EN MOVILIDAD", "intro": "Desarrollamos software que analiza videos para generar métricas de observación visual: estimar si una persona orienta la mirada hacia la publicidad y, cuando la geometría y la calibración lo permiten, hacia qué zona. Combina inteligencia artificial, visión computacional y reportes con evidencia visual.", "anchor": "¿Cuándo se orienta la mirada hacia la publicidad y qué zonas pueden identificarse?", "limit": "Alcance del piloto: estima observación visual, no atención cognitiva, recuerdo ni eficacia publicitaria. La identificación de zonas depende de calibración y calidad de captura; la precisión en condiciones reales sigue pendiente de validación.", "steps": ["Definimos el contexto de movilidad y la pregunta publicitaria. El objetivo es convertir videos en evidencia revisable sobre orientación visual, manteniendo separados observación y efecto del anuncio.", "Precisamos las métricas que buscamos obtener: estados de observación y su evolución en el tiempo, condiciones evaluables y zonas identificables según la calibración.", "Diseñamos el flujo de software: seguimiento de persona, calidad de imagen, estimación ocular, agregación por intervalos y generación de reportes. La validación exige una referencia independiente.", "El diseño se adapta al video: protocolo de captura, posición de cámara, geometría de la pantalla, condiciones de iluminación y calibración. No requiere imponer un cuestionario.", "Revisamos visibilidad, oclusiones y calidad. El motor debe distinguir intervalos evaluables de periodos sin evidencia suficiente, evitando interpretarlos automáticamente como ausencia de observación.", "El software aplica IA y visión computacional para seguir al sujeto, estimar dirección ocular y generar estados por intervalos. Su interpretación espacial depende de la calibración disponible.", "Analizamos los patrones temporales y su evidencia visual para identificar periodos de posible observación. Las zonas se interpretan solo cuando la geometría permite hacerlo; no inferimos comprensión o recuerdo.", "Generamos reportes por video con métricas, estados temporales y evidencia visual. El piloto conserva límites de calibración y requiere validar error y cobertura antes de ofrecer precisión en condiciones reales."], "outputs": ["Una definición de observación y del contexto de captura.", "Una pregunta medible, separada de las afirmaciones sobre atención.", "Una relación explícita entre señales, métricas y referencia de validación.", "Un protocolo de captura y calibración; no un cuestionario por defecto.", "Intervalos evaluables y límites de calidad identificados.", "Estimaciones temporales con sus restricciones de calibración.", "Interpretaciones acotadas y necesidades de validación independientes.", "Reportes del piloto y un plan de validación antes de escalar."], "built": "Un motor de auditoría de video con selección y seguimiento de personas, estimación de dirección ocular, evaluación de calidad de imagen y procesamiento por intervalos de tiempo.", "method": "El software sigue al sujeto, evalúa si la imagen permite analizarlo, estima señales de orientación visual y las organiza temporalmente. La relación cámara–pantalla permite interpretar zonas de observación cuando está calibrada.", "delivered": "Reportes por video con estados de observación por intervalo, métricas temporales y evidencia visual para revisar las estimaciones y los periodos sin información suficiente."}];
let intelligenceStage=0,applicationStage=0,applicationIndex=0;
function renderIntelligence(){
 const item=intelligenceStages[intelligenceStage];
 document.querySelectorAll('[data-intelligence-stage]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.intelligenceStage)===intelligenceStage)));
 document.querySelector('[data-intelligence-number]').textContent='ETAPA '+String(intelligenceStage+1).padStart(2,'0')+' DE 08';
 document.querySelector('[data-intelligence-title]').textContent=item.name;
 document.querySelectorAll('[data-intelligence]').forEach(e=>{e.textContent=item[e.dataset.intelligence]});
}
function renderApplication(){
 const item=applications[applicationIndex];
 document.querySelectorAll('[data-application]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.application)===applicationIndex)));
 document.querySelectorAll('[data-application-field]').forEach(e=>{e.textContent=item[e.dataset.applicationField]});
 document.querySelectorAll('[data-application-stage]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.applicationStage)===applicationStage)));
 document.querySelector('[data-application-number]').textContent='ETAPA '+String(applicationStage+1).padStart(2,'0')+' DE 08';
 document.querySelector('[data-application-title]').textContent=intelligenceStages[applicationStage].name;
 document.querySelector('[data-application-text]').textContent=item.steps[applicationStage];
 document.querySelector('[data-application-return]').textContent=item.outputs ? item.outputs[applicationStage] : intelligenceStages[applicationStage].output;
}
document.querySelectorAll('[data-intelligence-stage]').forEach(b=>b.addEventListener('click',()=>{intelligenceStage=Number(b.dataset.intelligenceStage);renderIntelligence()}));
document.querySelectorAll('[data-application]').forEach(b=>b.addEventListener('click',()=>{applicationIndex=Number(b.dataset.application);renderApplication()}));
document.querySelectorAll('[data-application-stage]').forEach(b=>b.addEventListener('click',()=>{applicationStage=Number(b.dataset.applicationStage);renderApplication()}));
